// newOAuthSessionID returns a cryptographically random 128-bit session ID as
// lowercase hexadecimal, or a generic invalid-login error if randomness fails.
func newOAuthSessionID() (string, error) {
	value := make([]byte, 16)
	if _, err := rand.Read(value); err != nil {
		return "", errLoginInvalid
	}
	return hex.EncodeToString(value), nil
}

