// oauthResolvedConfig resolves the authentication context, applies global
// OAuth fallbacks only without a selected environment, and reports discovery
// URLs and whether OAuth login is enabled.
func oauthResolvedConfig(args []string) (string, string, authEnvironmentConfig, []string, bool, error) {
	base, env, cfg, err := resolveAuthContext(args, readConfig())
	if err != nil {
		return "", "", authEnvironmentConfig{}, nil, false, err
	}
	// Global fallbacks apply only when no environment was selected: the
	// default config already carries the package globals, and a selected
	// environment's values are authoritative. `null` clears an inherited
	// value, so an environment that clears scopes or token parameters keeps
	// them empty instead of resurrecting the globals (device and browser
	// grants then send only what that environment actually declares).
	environmentPicked := env != ""
	cfg.OAuthClientID = oauthGlobalFallback(environmentPicked, cfg.OAuthClientID, oauthBuiltInClientID)
	cfg.OAuthTokenURL = oauthGlobalFallback(environmentPicked, cfg.OAuthTokenURL, oauthTokenURL)
	cfg.OAuthDiscoveryURL = oauthGlobalFallback(environmentPicked, cfg.OAuthDiscoveryURL, oauthDiscoveryURL)
	cfg.OAuthDeviceAuthorizationURL = oauthGlobalFallback(environmentPicked, cfg.OAuthDeviceAuthorizationURL, oauthDeviceURL)
	cfg.OAuthAuthorizationURL = oauthGlobalFallback(environmentPicked, cfg.OAuthAuthorizationURL, oauthAuthorizationURL)
	cfg.OAuthRedirectURI = oauthGlobalFallback(environmentPicked, cfg.OAuthRedirectURI, oauthRedirectURI)
	cfg.OAuthIssuer = oauthGlobalFallback(environmentPicked, cfg.OAuthIssuer, oauthIssuer)
	cfg.OAuthLoginMethod = oauthGlobalFallback(environmentPicked, cfg.OAuthLoginMethod, oauthLoginMethod)
	cfg.OAuthOrganizationParameter = oauthGlobalFallback(environmentPicked, cfg.OAuthOrganizationParameter, oauthOrganizationParameter)
	cfg.AuthURL = oauthGlobalFallback(environmentPicked, cfg.AuthURL, browserApprovalURL)
	cfg.OAuthScopes = oauthRefreshScopes(environmentPicked, cfg.OAuthScopes, oauthScopes)
	cfg.OAuthTokenParams = oauthRefreshTokenParams(environmentPicked, cfg.OAuthTokenParams, oauthTokenParams)
	discovery := oauthDiscoveryURLsFor(cfg.OAuthIssuer, cfg.OAuthDiscoveryURL, cfg.OAuthTokenURL)
	enabled := cfg.OAuthTokenURL != "" || len(discovery) > 0
	if !enabled {
		enabled = oauthLoginEnabledDefault
	}
	return base, env, cfg, discovery, enabled, nil
}

// cloneStringMap returns an independent shallow copy and normalizes nil or
// empty input to an empty map.
func cloneStringMap(input map[string]string) map[string]string {
	if len(input) == 0 {
		return map[string]string{}
	}
	out := make(map[string]string, len(input))
	for k, v := range input {
		out[k] = v
	}
	return out
}

