// oauthClientIDFor resolves the device-login client ID: the
// --client-id flag, then the <PREFIX>_CLIENT_ID environment variable,
// then the project's built-in.
func oauthClientIDFor(args []string, cfg authEnvironmentConfig) string {
	if v := authFlagValue(args, "--client-id"); v != "" {
		return v
	}
	if v := os.Getenv(authPrefix + "_CLIENT_ID"); v != "" {
		return v
	}
	return cfg.OAuthClientID
}

// oauthLoginOrganization validates and returns the requested provider
// organization, or an empty string when none was requested.
func oauthLoginOrganization(args []string, cfg authEnvironmentConfig) (string, error) {
	id := authFlagValue(args, "--login-organization")
	if id == "" {
		return "", nil
	}
	if cfg.OAuthOrganizationParameter == "" || cfg.IdentityOrganization == "" {
		return "", errLoginInvalid
	}
	if len(id) > 512 {
		return "", errLoginInvalid
	}
	for i := 0; i < len(id); i++ {
		if id[i] <= 0x20 || id[i] == 0x7f {
			return "", errLoginInvalid
		}
	}
	return id, nil
}

// explicitNonInteractive reports whether the run explicitly opted out
// of interactive login flows with --non-interactive.
func explicitNonInteractive() bool {
	return os.Getenv(authPrefix+"_EXPLICIT_NONINTERACTIVE") != ""
}

// oauthEndpoint validates a login endpoint: HTTPS only (loopback HTTP is
// allowed for development), no embedded credentials, no fragment, and no
// control characters.
func oauthEndpoint(value string) (string, error) {
	if value == "" || len(value) > 8192 {
		return "", errLoginInvalid
	}
	for i := 0; i < len(value); i++ {
		if value[i] <= 0x20 || value[i] == 0x7f {
			return "", errLoginInvalid
		}
	}
	parsed, err := url.Parse(value)
	if err != nil || parsed.Host == "" {
		return "", errLoginInvalid
	}
	host := parsed.Hostname()
	local := host == "localhost" || host == "127.0.0.1" || host == "::1"
	if (parsed.Scheme != "https" && !(parsed.Scheme == "http" && local)) || parsed.User != nil || parsed.Fragment != "" {
		return "", errLoginInvalid
	}
	return parsed.String(), nil
}

// oauthNumber reads a JSON number field, rejecting absent or non-numeric
// values (a present null counts as invalid).
func oauthNumber(raw json.RawMessage) (float64, bool) {
	if len(raw) == 0 || bytes.Equal(raw, []byte("null")) {
		return 0, false
	}
	var value float64
	if json.Unmarshal(raw, &value) != nil {
		return 0, false
	}
	return value, true
}

// oauthSeconds validates a positive polling deadline in seconds with
// an upper bound no polling hint can reasonably exceed. Token
// lifetimes use oauthTokenSeconds instead: a 30-day access token is
// as legitimate as a 30-minute one.
func oauthSeconds(raw json.RawMessage) (float64, bool) {
	v, ok := oauthNumber(raw)
	if !ok || !(v > 0) || v > 900000 {
		return 0, false
	}
	return v, true
}

// maxSafeTokenMilliseconds is the ceiling applied to token lifetimes:
// large enough for any real grant, small enough that adding its
// milliseconds to the current time cannot overflow.
const maxSafeTokenMilliseconds = 9007199254740991

// oauthTokenSeconds returns a positive JSON token lifetime whose rounded-up
// milliseconds fit within the duration-safe ceiling.
func oauthTokenSeconds(raw json.RawMessage) (float64, bool) {
	v, ok := oauthNumber(raw)
	if !ok || !(v > 0) || math.Ceil(v*1000) > maxSafeTokenMilliseconds {
		return 0, false
	}
	return v, true
}

// oauthText validates a string field from a login response: a JSON
// string, nonempty once trimmed, bounded length, no control
// characters.
func oauthText(raw json.RawMessage, limit int) (string, bool) {
	if len(raw) == 0 {
		return "", false
	}
	var value string
	if json.Unmarshal(raw, &value) != nil {
		return "", false
	}
	if strings.TrimSpace(value) == "" || len(value) > limit {
		return "", false
	}
	for i := 0; i < len(value); i++ {
		if value[i] < 0x20 || value[i] == 0x7f {
			return "", false
		}
	}
	return value, true
}

// oauthDeviceLogin runs the RFC 8628 device grant: read a device code
// from the provider, hand the person the verification URL and user
// code, then poll the token endpoint until the grant is approved,
// denied, or expires. Only authorization_pending and slow_down keep
// polling; every deadline includes the response body, and
// cancellation interrupts the waits.
func oauthDeviceLogin(ctx context.Context, clientID string, cfg authEnvironmentConfig, discoveryURLs []string, args []string, stdout, stderr io.Writer) (*oauthSession, error) {
	if clientID == "" || len(clientID) > 65536 || strings.TrimSpace(clientID) == "" {
		return nil, errLoginInvalid
	}
	for i := 0; i < len(clientID); i++ {
		if clientID[i] < 0x20 || clientID[i] == 0x7f {
			return nil, errLoginInvalid
		}
	}
	deviceURL, tokenURL := cfg.OAuthDeviceAuthorizationURL, cfg.OAuthTokenURL
	revocationURL := ""
	for _, candidate := range discoveryURLs {
		if deviceURL != "" && tokenURL != "" {
			// An explicit issuer is still a contract when both endpoints
			// are configured: it must be a valid endpoint without a
			// query, exactly like browser OAuth, before the early break.
			if cfg.OAuthIssuer != "" {
				if endpoint, issuerErr := oauthEndpoint(cfg.OAuthIssuer); issuerErr != nil {
					return nil, issuerErr
				} else if parsedIssuer, queryErr := url.Parse(endpoint); queryErr != nil || parsedIssuer.RawQuery != "" {
					return nil, errLoginInvalid
				}
			}
			break
		}
		response, err := oauthRequest(ctx, http.MethodGet, candidate, "", nil, 10*time.Second)
		if err != nil {
			return nil, err
		}
		if response.status != http.StatusOK {
			continue
		}
		if cfg.OAuthIssuer != "" {
			issuer, ok := oauthText(response.body["issuer"], 8192)
			if !ok || issuer != cfg.OAuthIssuer {
				return nil, errLoginInvalid
			}
		}
		if deviceURL == "" {
			if v, ok := oauthText(response.body["device_authorization_endpoint"], 8192); ok {
				deviceURL, err = oauthEndpoint(v)
				if err != nil {
					return nil, err
				}
			}
		}
		if tokenURL == "" {
			if v, ok := oauthText(response.body["token_endpoint"], 8192); ok {
				tokenURL, err = oauthEndpoint(v)
				if err != nil {
					return nil, err
				}
			}
		}
		if raw, present := response.body["revocation_endpoint"]; present {
			v, ok := oauthText(raw, 8192)
			if !ok {
				return nil, errLoginInvalid
			}
			revocationURL, err = oauthEndpoint(v)
			if err != nil {
				return nil, err
			}
		}
	}
	if deviceURL == "" || tokenURL == "" {
		return nil, errLoginInvalid
	}
	startForm := url.Values{}
	// Token params first; the reserved protocol fields always win, so
	// configuration cannot change the client or the scope.
	for key, value := range cfg.OAuthTokenParams {
		startForm.Set(key, value)
	}
	startForm.Set("client_id", clientID)
	if len(cfg.OAuthScopes) > 0 {
		startForm.Set("scope", strings.Join(cfg.OAuthScopes, " "))
	}
	start, err := oauthRequest(ctx, http.MethodPost, deviceURL, "application/x-www-form-urlencoded", []byte(startForm.Encode()), 30*time.Second)
	if err != nil {
		return nil, err
	}
	if start.status != http.StatusOK {
		return nil, errLoginRequest
	}
	deviceCode, okCode := oauthText(start.body["device_code"], 65536)
	userCode, okUser := oauthText(start.body["user_code"], 512)
	verificationURI, okURI := oauthText(start.body["verification_uri"], 8192)
	expiresIn, okExpires := oauthSeconds(start.body["expires_in"])
	if !okCode || !okUser || !okURI || !okExpires {
		return nil, errLoginInvalid
	}
	if _, err := oauthEndpoint(verificationURI); err != nil {
		return nil, errLoginInvalid
	}
	displayURI := verificationURI
	if raw, present := start.body["verification_uri_complete"]; present {
		v, ok := oauthText(raw, 8192)
		if !ok {
			return nil, errLoginInvalid
		}
		if _, err := oauthEndpoint(v); err != nil {
			return nil, errLoginInvalid
		}
		displayURI = v
	}
	intervalSec := 5.0
	if raw, present := start.body["interval"]; present {
		v, ok := oauthNumber(raw)
		if !ok || v < 0 || v > 900000 {
			return nil, errLoginInvalid
		}
		intervalSec = v
		if intervalSec < 1 {
			intervalSec = 1
		}
	}
	capped := expiresIn
	if capped > 900 {
		capped = 900
	}
	deadline := time.Now().Add(time.Duration(capped * float64(time.Second)))
	fmt.Fprintln(stderr, "Open "+displayURI+" and enter code: "+userCode)
	if modeFor(args, stdout) == agentMode {
		event, _ := json.Marshal(map[string]any{"event": "device_code", "verification_uri": displayURI, "user_code": userCode, "expires_in": capped})
		fmt.Fprintln(stderr, string(event))
	}
	pollForm := url.Values{}
	// Token params first; the reserved protocol fields always win.
	for key, value := range cfg.OAuthTokenParams {
		pollForm.Set(key, value)
	}
	pollForm.Set("grant_type", "urn:ietf:params:oauth:grant-type:device_code")
	pollForm.Set("device_code", deviceCode)
	pollForm.Set("client_id", clientID)
	for {
		pause := time.Duration(intervalSec * float64(time.Second))
		if until := time.Until(deadline); until < pause {
			pause = until
		}
		if pause < 0 {
			pause = 0
		}
		timer := time.NewTimer(pause)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, errLoginCancelled
		case <-timer.C:
		}
		if !time.Now().Before(deadline) {
			return nil, errLoginExpired
		}
		timeout := 30 * time.Second
		if until := time.Until(deadline); until < timeout {
			timeout = until
		}
		if timeout <= 0 {
			return nil, errLoginExpired
		}
		poll, err := oauthDeviceRequest(ctx, http.MethodPost, tokenURL, "application/x-www-form-urlencoded", []byte(pollForm.Encode()), timeout)
		if err != nil {
			if ctx.Err() != nil {
				return nil, errLoginCancelled
			}
			if errors.Is(err, errLoginTimedOut) {
				intervalSec *= 2
				continue
			}
			return nil, err
		}
		if !time.Now().Before(deadline) {
			return nil, errLoginExpired
		}
		if poll.status == http.StatusBadRequest {
			kind, _ := oauthText(poll.body["error"], 128)
			switch kind {
			case "authorization_pending":
				continue
			case "slow_down":
				intervalSec += 5
				continue
			case "access_denied":
				return nil, errLoginDenied
			case "expired_token":
				return nil, errLoginExpired
			}
		}
		if poll.status != http.StatusOK {
			return nil, errLoginRequest
		}
		accessToken, okAccess := oauthText(poll.body["access_token"], 65536)
		if !okAccess {
			return nil, errLoginInvalid
		}
		if kind, ok := oauthText(poll.body["token_type"], 128); !ok || strings.ToLower(kind) != "bearer" {
			return nil, errLoginInvalid
		}
		if _, present := poll.body["error"]; present {
			return nil, errLoginInvalid
		}
		refreshToken := ""
		if raw, present := poll.body["refresh_token"]; present {
			v, ok := oauthText(raw, 65536)
			if !ok {
				return nil, errLoginInvalid
			}
			refreshToken = v
		}
		expiresAt := int64(0)
		if raw, present := poll.body["expires_in"]; present {
			v, ok := oauthTokenSeconds(raw)
			if !ok {
				return nil, errLoginInvalid
			}
			expiresAt = time.Now().UnixMilli() + int64(v*1000)
		}
		scopes := []string{}
		if raw, present := poll.body["scope"]; present {
			var scopeText string
			if json.Unmarshal(raw, &scopeText) != nil {
				return nil, errLoginInvalid
			}
			scopes = strings.Fields(scopeText)
		}
		return &oauthSession{AccessToken: accessToken, ExpiresAt: expiresAt, RefreshToken: refreshToken, TokenURL: tokenURL, ClientID: clientID, RevocationURL: revocationURL, Scopes: scopes}, nil
	}
}

// browserApprovalLogin posts a PKCE-shaped challenge to the API's
// /start route, shows the person the verification URL (opening it
// unless headless), and polls /status until the API hands back the
// key it minted for this CLI. Only a rate-limited poll is retried:
// other failures may have consumed the one-use credential.
func browserApprovalLogin(ctx context.Context, approvalURL string, headless bool, args []string, stdout, stderr io.Writer) (*mintedCredential, error) {
	base, err := oauthEndpoint(approvalURL)
	if err != nil {
		return nil, errLoginInvalid
	}
	parsed, err := url.Parse(base)
	if err != nil || parsed.RawQuery != "" {
		return nil, errLoginInvalid
	}
	target := strings.TrimRight(base, "/")
	verifierBytes := make([]byte, 32)
	if _, err := rand.Read(verifierBytes); err != nil {
		return nil, errLoginInvalid
	}
	verifier := base64.RawURLEncoding.EncodeToString(verifierBytes)
	sum := sha256.Sum256([]byte(verifier))
	challenge := base64.RawURLEncoding.EncodeToString(sum[:])
	source := "cli"
	if modeFor(args, stdout) == agentMode {
		source = "agent"
	}
	hostname, _ := os.Hostname()
	name := bin + " CLI on " + hostname
	startBody, _ := json.Marshal(map[string]string{"code_challenge": challenge, "name": name, "source": source})
	response, err := oauthRequest(ctx, http.MethodPost, target+"/start", "application/json", startBody, 15*time.Second)
	if err != nil {
		return nil, err
	}
	if response.status != http.StatusOK {
		return nil, fmt.Errorf("browser login start failed (HTTP %d); wait and start a new login", response.status)
	}
	session, okSession := oauthText(response.body["session"], 65536)
	verificationURL, okURL := oauthText(response.body["verification_url"], 8192)
	if !okSession || !okURL {
		return nil, errLoginInvalid
	}
	if _, err := oauthEndpoint(verificationURL); err != nil {
		return nil, errLoginInvalid
	}
	expiresIn := 600.0
	if raw, present := response.body["expires_in"]; present {
		v, ok := oauthSeconds(raw)
		if !ok {
			return nil, errLoginInvalid
		}
		expiresIn = v
	}
	if expiresIn > 600 {
		expiresIn = 600
	}
	intervalSec := 3.0
	if raw, present := response.body["interval"]; present {
		v, ok := oauthNumber(raw)
		if !ok || v < 0 || v > 900000 {
			return nil, errLoginInvalid
		}
		intervalSec = v
		if intervalSec < 1 {
			intervalSec = 1
		}
	}
	deadline := time.Now().Add(time.Duration(expiresIn * float64(time.Second)))
	nextPause := time.Duration(intervalSec * float64(time.Second))
	fmt.Fprintln(stderr, "Approve this CLI in your browser: "+verificationURL)
	if headless {
		event, _ := json.Marshal(map[string]any{"event": "browser_approval", "verification_url": verificationURL, "expires_in": int(expiresIn), "note": "Give this URL to the user; polling until they approve or it expires."})
		fmt.Fprintln(stderr, string(event))
	} else {
		openURL(verificationURL)
	}
	for {
		pause := nextPause
		nextPause = time.Duration(intervalSec * float64(time.Second))
		if until := time.Until(deadline); until < pause {
			pause = until
		}
		if pause < 0 {
			pause = 0
		}
		timer := time.NewTimer(pause)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, errLoginCancelled
		case <-timer.C:
		}
		if !time.Now().Before(deadline) {
			return nil, errLoginExpired
		}
		timeout := 15 * time.Second
		if until := time.Until(deadline); until < timeout {
			timeout = until
		}
		if timeout <= 0 {
			return nil, errLoginExpired
		}
		body, _ := json.Marshal(map[string]string{"session": session, "code_verifier": verifier})
		poll, err := oauthRequest(ctx, http.MethodPost, target+"/status", "application/json", body, timeout)
		if err != nil {
			if ctx.Err() != nil {
				return nil, errLoginCancelled
			}
			// A failed poll is not replayed: the one-use credential may
			// already have been consumed.
			reason := "transport failure"
			if errors.Is(err, errLoginTimedOut) {
				reason = "request timed out"
			} else if errors.Is(err, errLoginInvalid) {
				reason = "invalid response"
			}
			return nil, fmt.Errorf("browser login credential poll failed (%s); the credential may have been issued; review and revoke any unused CLI key in the console, then start a new login", reason)
		}
		if !time.Now().Before(deadline) {
			return nil, errLoginExpired
		}
		if poll.status == http.StatusTooManyRequests {
			// /status rejects rate-limited requests before redeeming the
			// approval. Never extend the session deadline while waiting.
			nextPause = browserApprovalRetryDelay(poll.retryAfter, nextPause)
			fmt.Fprintln(stderr, "Browser login credential poll rate limited (HTTP 429); waiting before retrying.")
			continue
		}
		if poll.status != http.StatusOK {
			return nil, fmt.Errorf("browser login credential poll failed (HTTP %d); the credential may have been issued; review and revoke any unused CLI key in the console, then start a new login", poll.status)
		}
		status, _ := oauthText(poll.body["status"], 64)
		switch status {
		case "pending":
			continue
		case "denied":
			return nil, errLoginDenied
		case "expired":
			return nil, errLoginExpired
		case "consumed":
			return nil, errors.New("browser login credential poll returned consumed; this request cannot be replayed; review and revoke any unused CLI key in the console, then start a new login")
		case "not_found", "verifier_mismatch":
			return nil, fmt.Errorf("browser login credential poll returned %s; start a new login", status)
		}
		if status != "complete" {
			return nil, errLoginInvalid
		}
		apiKey, okKey := oauthText(poll.body["api_key"], 65536)
		if !okKey {
			return nil, errLoginInvalid
		}
		keyName := name
		if raw, present := poll.body["key_name"]; present {
			v, ok := oauthText(raw, 1024)
			if !ok {
				return nil, errLoginInvalid
			}
			keyName = v
		}
		orgID := ""
		if raw, present := poll.body["org_id"]; present {
			v, ok := oauthText(raw, 1024)
			if !ok {
				return nil, errLoginInvalid
			}
			orgID = v
		}
		return &mintedCredential{APIKey: apiKey, Via: "browser", KeyName: keyName, OrgID: orgID, RevocationURL: target + "/revoke"}, nil
	}
}

func browserApprovalRetryDelay(raw string, minimum time.Duration) time.Duration {
	delay := 5 * time.Second
	if seconds, err := strconv.ParseUint(raw, 10, 32); err == nil && seconds <= 600 {
		delay = time.Duration(seconds) * time.Second
	} else if date, err := http.ParseTime(raw); err == nil {
		if until := time.Until(date); until > 0 && until <= 10*time.Minute {
			delay = until
		}
	}
	if delay < minimum {
		delay = minimum
	}
	return delay
}

// resolveBrowserApprovalURL validates approvalURL and, when it targets the
// default API origin, rewrites that origin to the selected base URL.
func resolveBrowserApprovalURL(baseURL, approvalURL string) (string, error) {
	target, err := oauthEndpoint(approvalURL)
	if err != nil {
		return "", err
	}
	if defaultBaseURL == "" || baseURL == "" {
		return target, nil
	}
	defaultParsed, err := url.Parse(defaultBaseURL)
	if err != nil {
		return target, nil
	}
	targetParsed, err := url.Parse(target)
	if err != nil {
		return "", errLoginInvalid
	}
	selected, err := oauthEndpoint(baseURL)
	if err != nil {
		return "", errLoginInvalid
	}
	selectedParsed, err := url.Parse(selected)
	if err != nil {
		return "", errLoginInvalid
	}
	if targetParsed.Scheme == defaultParsed.Scheme && targetParsed.Host == defaultParsed.Host {
		targetParsed.Scheme = selectedParsed.Scheme
		targetParsed.Host = selectedParsed.Host
	}
	return targetParsed.String(), nil
}

// refreshStoredOAuth rotates a stored OAuth session's access token
// before a request replays an expired one. Flags and environment
// credentials win over storage, so they never trigger a refresh; a
// pasted stored token on the same credential wins too. A session
// already marked refresh-pending fails closed: its refresh token may
// have been consumed by an interrupted exchange and is never reused.
func refreshStoredOAuth(ctx context.Context, args, surfaceArgs []string, base, env string, authCfg authEnvironmentConfig) error {
	stored := readStoredAuth()
	session := stored.OAuth
	if session != nil && session.RefreshPending {
		return errors.New("the previous OAuth refresh did not finish safely; log in again — its refresh token will not be reused")
	}
	if session == nil || session.AccessToken == "" || session.RefreshToken == "" || session.TokenURL == "" || session.ClientID == "" {
		return nil
	}
	if err := validateStoredOAuthBinding(session, base, env, authCfg); err != nil {
		return err
	}
	if authFlagValue(args, "--token") != "" || os.Getenv(authCredentialEnvs["token"]) != "" || stored.Scalars[authCredentialKeys["token"]] != "" {
		return nil
	}
	if oauthSessionFresh(session.ExpiresAt) {
		return nil
	}
	if hasFlag(args, "--dry-run") {
		return errors.New("dry-run cannot refresh saved OAuth credentials; run login or execute the command without --dry-run")
	}
	unlock, err := lockStoredAuth()
	if err != nil {
		return err
	}
	defer unlock()
	// Re-read under the lock: another process may have rotated it first.
	stored = readStoredAuth()
	session = stored.OAuth
	if session == nil {
		return nil
	}
	if session.RefreshPending {
		return errors.New("the previous OAuth refresh did not finish safely; log in again — its refresh token will not be reused")
	}
	if oauthSessionFresh(session.ExpiresAt) {
		return nil
	}
	if err := validateStoredOAuthBinding(session, base, env, authCfg); err != nil {
		return err
	}
	if err := validateStoredIdentity(stored, authCfg); err != nil {
		return err
	}
	if identityPolicyConfigured(authCfg) {
		op := findOp(whoamiResource, whoamiCommand)
		if op == nil {
			return errors.New("the configured identity operation is not available in this package")
		}
		if _, message, _ := identitySurfaceError(op, surfaceArgs); message != "" {
			return errors.New(message)
		}
	}
	pending := stored
	pending.OAuth = &oauthSession{SessionID: session.SessionID, AccessToken: session.AccessToken, RefreshToken: session.RefreshToken, ExpiresAt: session.ExpiresAt, TokenURL: session.TokenURL, ClientID: session.ClientID, RevocationURL: session.RevocationURL, Scopes: session.Scopes, APIBaseURL: session.APIBaseURL, Issuer: session.Issuer, ConfiguredClientID: session.ConfiguredClientID, Binding: session.Binding, RefreshPending: true}
	if err := writeStoredAuth(pending); err != nil {
		return err
	}
	next, err := exchangeRefreshToken(ctx, session, authCfg)
	if err != nil {
		return err
	}
	stored.OAuth = next
	if identityPolicyConfigured(authCfg) {
		evidence, verifyErr := verifyRefreshedIdentity(ctx, stored, base, env, authCfg, stored.Identity.Values, surfaceArgs)
		if verifyErr != nil {
			return verifyErr
		}
		stored.Identity = evidence
	}
	return writeStoredAuth(stored)
}

// exchangeRefreshToken runs the refresh-token grant for a stored
// session and returns the rotated session. On any failure the
// refresh-pending marker stays set: the provider may have consumed
// the refresh token even when no response arrived, so logging in
// again is the only safe recovery.
func exchangeRefreshToken(ctx context.Context, session *oauthSession, authCfg authEnvironmentConfig) (*oauthSession, error) {
	form := url.Values{}
	// Token params first; the reserved protocol fields always win.
	for key, value := range authCfg.OAuthTokenParams {
		form.Set(key, value)
	}
	form.Set("grant_type", "refresh_token")
	form.Set("refresh_token", session.RefreshToken)
	form.Set("client_id", session.ClientID)
	response, err := oauthRequest(ctx, http.MethodPost, session.TokenURL, "application/x-www-form-urlencoded", []byte(form.Encode()), 30*time.Second)
	if err != nil {
		return nil, err
	}
	if response.status != http.StatusOK {
		return nil, errLoginRequest
	}
	accessToken, ok := oauthText(response.body["access_token"], 65536)
	if !ok {
		return nil, errLoginInvalid
	}
	if kind, ok := oauthText(response.body["token_type"], 128); !ok || strings.ToLower(kind) != "bearer" {
		return nil, errLoginInvalid
	}
	next := &oauthSession{SessionID: session.SessionID, AccessToken: accessToken, RefreshToken: session.RefreshToken, TokenURL: session.TokenURL, ClientID: session.ClientID, RevocationURL: session.RevocationURL, Scopes: session.Scopes, APIBaseURL: session.APIBaseURL, Issuer: session.Issuer, ConfiguredClientID: session.ConfiguredClientID, Binding: session.Binding}
	if raw, present := response.body["expires_in"]; present {
		v, ok := oauthTokenSeconds(raw)
		if !ok {
			return nil, errLoginInvalid
		}
		next.ExpiresAt = time.Now().UnixMilli() + int64(v*1000)
	}
	if raw, present := response.body["refresh_token"]; present {
		v, ok := oauthText(raw, 65536)
		if !ok {
			return nil, errLoginInvalid
		}
		next.RefreshToken = v
	}
	if raw, present := response.body["scope"]; present {
		var scopeText string
		if json.Unmarshal(raw, &scopeText) != nil {
			return nil, errLoginInvalid
		}
		next.Scopes = strings.Fields(scopeText)
	}
	return next, nil
}

// revokeBearer revokes a key the API minted for this CLI (browser
// approval) when logging out: best-effort cleanup, never surfaced as a
// hard failure.
func revokeBearer(endpoint, key string) bool {
	target, err := oauthEndpoint(endpoint)
	if err != nil {
		return false
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, target, nil)
	if err != nil {
		return false
	}
	req.Header.Set("Authorization", "Bearer "+key)
	req.Header.Set("Accept", "application/json")
	client := &http.Client{CheckRedirect: func(_ *http.Request, _ []*http.Request) error { return http.ErrUseLastResponse }}
	resp, err := client.Do(req)
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	return resp.StatusCode >= 200 && resp.StatusCode < 300
}

// revokeOAuthToken revokes a stored OAuth session's refresh (or, when
// there is none, access) token, so logging out ends the grant as
// well as the file.
func revokeOAuthToken(session *oauthSession) bool {
	if session.RevocationURL == "" {
		return false
	}
	target, err := oauthEndpoint(session.RevocationURL)
	if err != nil {
		return false
	}
	token := session.RefreshToken
	hint := "refresh_token"
	if session.RefreshToken == "" {
		token, hint = session.AccessToken, "access_token"
	}
	form := url.Values{"token": {token}, "token_type_hint": {hint}}
	if session.ClientID != "" {
		form.Set("client_id", session.ClientID)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, target, strings.NewReader(form.Encode()))
	if err != nil {
		return false
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")
	client := &http.Client{CheckRedirect: func(_ *http.Request, _ []*http.Request) error { return http.ErrUseLastResponse }}
	resp, err := client.Do(req)
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	return resp.StatusCode >= 200 && resp.StatusCode < 300
}

// lockStoredAuth serializes credential writes across processes with a
// claim-and-link protocol: a lock names a live owner, a dead owner's
// lock is reclaimed exactly once, and a busy store fails with a bounded
// diagnostic instead of blocking forever.
func lockStoredAuth() (func(), error) {
	dir := filepath.Dir(authPath())
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, err
	}
	lockPath := authPath() + ".lock"
	nonceBytes := make([]byte, 16)
	if _, err := rand.Read(nonceBytes); err != nil {
		return nil, err
	}
	nonce := hex.EncodeToString(nonceBytes)
	claimPath := lockPath + "." + nonce
	owner := "{\"pid\":" + strconv.Itoa(os.Getpid()) + ",\"nonce\":\"" + nonce + "\",\"started\":" + strconv.FormatInt(time.Now().UnixMilli(), 10) + "}"
	claim, err := os.OpenFile(claimPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return nil, err
	}
	if _, err := claim.WriteString(owner); err != nil {
		claim.Close()
		_ = os.Remove(claimPath)
		return nil, err
	}
	claim.Close()
	deadline := time.Now().Add(40 * time.Second)
	delay := 25 * time.Millisecond
	for {
		if err := os.Link(claimPath, lockPath); err == nil {
			return func() {
				_ = os.Remove(lockPath)
				_ = os.Remove(claimPath)
			}, nil
		} else if !errors.Is(err, os.ErrExist) {
			_ = os.Remove(claimPath)
			return nil, fmt.Errorf("cannot lock the credential store")
		}
		if reapDeadLockOwner(lockPath) {
			delay = 25 * time.Millisecond
			continue
		}
		if time.Now().After(deadline) {
			_ = os.Remove(claimPath)
			return nil, fmt.Errorf("the credential store is busy; wait for the other login or refresh to finish and retry")
		}
		jitter := time.Duration(int(nonceBytes[0]) % (int(delay/4) + 1))
		time.Sleep(delay + jitter)
		if delay < 400*time.Millisecond {
			delay *= 2
		}
	}
}

// reapDeadLockOwner removes a lock whose owner process died, exactly
// once per dead owner: the marker file prevents a delayed contender
// from removing a later owner's lock (the ABA race).
func reapDeadLockOwner(lockPath string) bool {
	ownerBytes, err := os.ReadFile(lockPath)
	if err != nil {
		return false
	}
	var owner struct {
		Pid     int    `json:"pid"`
		Nonce   string `json:"nonce"`
		Started int64  `json:"started"`
	}
	if json.Unmarshal(ownerBytes, &owner) != nil || owner.Pid <= 0 || !nonceHexRE(owner.Nonce) || processAlive(owner.Pid, owner.Started) {
		return false
	}
	markerPath := lockPath + ".reaped-" + owner.Nonce
	marker, err := os.OpenFile(markerPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return false
	}
	marker.Close()
	currentBytes, err := os.ReadFile(lockPath)
	if err != nil {
		return false
	}
	var current struct {
		Nonce string `json:"nonce"`
	}
	if json.Unmarshal(currentBytes, &current) == nil && current.Nonce == owner.Nonce {
		return os.Remove(lockPath) == nil
	}
	return false
}

// nonceHexRE reports whether a lock nonce has the exact shape lock
// owners write: 32 hex digits (16 random bytes).
func nonceHexRE(nonce string) bool {
	if len(nonce) != 32 {
		return false
	}
	for _, r := range nonce {
		if !(r >= 'a' && r <= 'f' || r >= '0' && r <= '9') {
			return false
		}
	}
	return true
}

// processAlive reports whether a pid still has a process. A probe that
// errors for any reason other than "no such process" means the process
// exists but is not ours to signal, and counts as alive, so a live
// owner's lock is never reclaimed.
func processAlive(pid int, startedAt int64) bool {
	found, err := os.FindProcess(pid)
	if err != nil {
		return false
	}
	if runtime.GOOS == "windows" {
		if startedAt > 0 && time.Now().UnixMilli()-startedAt > int64((2*time.Minute)/time.Millisecond) {
			return false
		}
		return true
	}
	err = found.Signal(syscall.Signal(0))
	return err == nil || !errors.Is(err, syscall.ESRCH)
}
